// The type declarations the package ships (generated by `npm run types` at pack time) compile under `strict` with
// `skipLibCheck` off, as a TypeScript project that imports the package compiles them.
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { mkdtempSync, readdirSync, readFileSync, rmSync } from 'node:fs';
import { createRequire } from 'node:module';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { test } from 'node:test';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
// The compiler's own command, as its package.json names it (the package exports no path to it).
const typescript = path.dirname(createRequire(import.meta.url).resolve('typescript/package.json'));
const tsc = path.join(typescript, JSON.parse(readFileSync(path.join(typescript, 'package.json'), 'utf8')).bin.tsc);

test('the generated type declarations compile under strict', () => {
  const out = mkdtempSync(path.join(tmpdir(), 'xsolana-types-'));
  try {
    execFileSync(process.execPath, [tsc, '-p', path.join(root, 'tsconfig.types.json'), '--outDir', out], { cwd: root });
    const files = readdirSync(out, { recursive: true }).filter((f) => /\.d\.m?ts$/.test(f)).map((f) => path.join(out, f));
    assert.ok(files.length > 20, `only ${files.length} declaration files`);
    const options = ['--strict', '--noEmit', '--skipLibCheck', 'false', '--target', 'es2022', '--module', 'nodenext', '--moduleResolution', 'nodenext'];
    try {
      execFileSync(process.execPath, [tsc, ...options, ...files], { cwd: out, encoding: 'utf8' });
    } catch (err) {
      assert.fail(`the declarations don't compile:\n${err.stdout}`);
    }
  } finally {
    rmSync(out, { recursive: true, force: true });
  }
});
